	@Test
	void publicationWhoseFeaturesTheCalibrationRefusesLeavesThePlanningRevision(@TempDir Path directory)
			throws Exception {
		LmdbOperatorFeedbackStats stats = stats(directory, new AtomicLong());
		// The first observation initializes the applicability's calibration with a known range width.
		publish(stats, contract(logical("calibrated"), APPLICABILITY, KNOWN_RANGE, LOGICAL), 7L, 7.0d);
		assertNotNull(stats.logicalPosterior(logical("calibrated"), APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS),
				"COVERAGE_PREREQUISITE: the first observation is admitted");

		Snapshot before = Snapshot.of(stats);
		publish(stats, contract(logical("refused"), APPLICABILITY, ROWS_ONLY, LOGICAL), 9L, 9.0d);

		assertAll(
				() -> assertEquals(before.clock() + 1L, stats.observationClock(),
						"COVERAGE_PREREQUISITE: the publication is accepted and ticks the observation clock"),
				() -> assertNull(stats.logicalPosterior(logical("refused"), APPLICABILITY,
						FrontierCostDimension.OUTPUT_ROWS),
						"COVERAGE_PREREQUISITE: an unknown range width is incompatible with the calibration"),
				() -> assertEquals(before.revision(), stats.planningRevision(),
						"a publication whose observation the calibration refuses changes nothing a planner reads"));
	}

