	@Test
	void boundOpenOfAnUnconditionedKeyLeavesThePlanningRevision(@TempDir Path directory) throws Exception {
		LmdbOperatorFeedbackStats stats = stats(directory, new AtomicLong());
		LearningApplicability unconditioned = unconditionedApplicability();
		RuntimeFeedbackContract contract = contract(logical("bound-open"), unconditioned, ROWS_ONLY,
				RuntimeFeedbackContract.ADMIT_LOGICAL | RuntimeFeedbackContract.ADMIT_PHYSICAL
						| RuntimeFeedbackContract.ADMIT_LIFECYCLE | RuntimeFeedbackContract.EXACT_FACT_ELIGIBLE);
		RuntimeFeedbackTarget target = stats.resolveRuntimeFeedbackTarget(contract, null, null, null,
				LmdbFeedbackReadAuthority.Publication.UNRESTRICTED, new String[] { "s" });
		MapBindingSet outer = new MapBindingSet(1);
		outer.addBinding("s", VF.createIRI("urn:test:planning-revision:outer"));
		target.open(outer);
		target.close(1L, 1.0d, 1L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, TerminationClassification.EXHAUSTED);
		target.recordActualPhysicalImplementation(contract.physicalImplementationId());

		Snapshot before = Snapshot.of(stats);
		stats.publishRuntimeFeedbackTargets(new RuntimeFeedbackTarget[] { target }, 1, true);

		assertAll(
				() -> assertEquals(before.clock() + 1L, stats.observationClock(),
						"COVERAGE_PREREQUISITE: the publication is accepted and ticks the observation clock"),
				() -> assertTrue(Double.isNaN(stats.exactCardinalityFact(logical("bound-open"), unconditioned)),
						"COVERAGE_PREREQUISITE: a bound open mints no context-free exact fact"),
				() -> assertNull(stats.logicalPosterior(logical("bound-open"), unconditioned,
						FrontierCostDimension.OUTPUT_ROWS), "COVERAGE_PREREQUISITE: nor a row observation"),
				() -> assertEquals(before.revision(), stats.planningRevision(),
						"a bound open of an unconditioned key teaches nothing a planner reads"));
	}

