	@Test
	void noOpTypedPublicationAdvancesWhileTheClockDecayedLegacyReaderHoldsEvidence(@TempDir Path directory)
			throws Exception {
		LmdbOperatorFeedbackStats stats = stats(directory, new AtomicLong());
		Join observed = join();
		complete(observed, 100L, 10.0d, 20.0d);
		observed.setJoinLeftBindingsConsumedActual(50L);
		observed.setJoinRightBindingsConsumedActual(100L);
		stats.recordOperatorOutcome(observed);
		LmdbOperatorFeedbackStats.OperatorEstimate legacyBefore = stats.estimate(join(), 200.0d, 100.0d, 10.0d,
				20.0d);
		assertNotNull(legacyBefore, "COVERAGE_PREREQUISITE: the legacy operator reader has evidence");

		RuntimeFeedbackContract contract = contract(logical("released"), APPLICABILITY, ROWS_ONLY, LOGICAL);
		RuntimeFeedbackTarget target = stats.resolveRuntimeFeedbackTarget(contract);
		complete(target, contract, 7L, 7.0d);
		target.release();
		long before = stats.planningRevision();
		stats.publishRuntimeFeedbackTargets(new RuntimeFeedbackTarget[] { target }, 1, true);
		LmdbOperatorFeedbackStats.OperatorEstimate legacyAfter = stats.estimate(join(), 200.0d, 100.0d, 10.0d,
				20.0d);

		assertAll(
				() -> assertNotEquals(legacyBefore.confidence(), legacyAfter.confidence(),
						"COVERAGE_PREREQUISITE: the legacy confidence decays with the observation clock"),
				() -> assertTrue(stats.planningRevision() > before,
						"while the clock-decayed legacy reader holds evidence every clock tick is planning evidence"));
	}

