	/*
	 * The production writer arms a cooldown only in the publication that also records a learned operator entry, which
	 * already versions every tick. The persisted cooldown is restored on its own, so the sidecar is the only route to a
	 * pending cooldown without that entry: this test arms it in an otherwise genuine sidecar.
	 */
	@Test
	void noOpTypedPublicationAdvancesWhileARuleSteeringCooldownIsPending(@TempDir Path directory) throws Exception {
		Path estimatorPath = estimatorPath(directory);
		LmdbOperatorFeedbackStats writer = new LmdbOperatorFeedbackStats(estimatorPath, () -> IDENTITY, () -> true,
				() -> 0L);
		publish(writer, contract(logical("persisted"), APPLICABILITY, ROWS_ONLY, LOGICAL), 7L, 7.0d);
		writer.persistIfDirty();
		Path sidecar = estimatorPath.resolveSibling(estimatorPath.getFileName() + ".operators");
		byte[] bytes = Files.readAllBytes(sidecar);
		ByteBuffer header = ByteBuffer.wrap(bytes);
		// version, snapshot identity, statement-mutation stamp, observation clock, then the rule-steering cooldown
		int cooldownOffset = Integer.BYTES + identityBytes() + Long.BYTES + Long.BYTES;
		long clock = header.getLong(cooldownOffset - Long.BYTES);
		assertEquals(writer.observationClock(), clock, "COVERAGE_PREREQUISITE: the header layout is as expected");
		assertEquals(0L, header.getLong(cooldownOffset), "COVERAGE_PREREQUISITE: no cooldown was armed");
		long cooldownUntil = clock + 4096L;
		header.putLong(cooldownOffset, cooldownUntil);
		Files.write(sidecar, bytes);

		LmdbOperatorFeedbackStats stats = new LmdbOperatorFeedbackStats(estimatorPath, () -> IDENTITY, () -> true,
				() -> 0L);
		assertEquals(clock, stats.observationClock(), "COVERAGE_PREREQUISITE: the sidecar loaded");
		long before = publishIntoReleasedCells(stats);
		long after = stats.planningRevision();

		// Read the restored cooldown back through the writer.
		publish(stats, contract(logical("dirty"), APPLICABILITY, ROWS_ONLY, LOGICAL), 7L, 7.0d);
		stats.persistIfDirty();
		assertAll(
				() -> assertEquals(cooldownUntil, ByteBuffer.wrap(Files.readAllBytes(sidecar)).getLong(cooldownOffset),
						"COVERAGE_PREREQUISITE: the pending cooldown was restored"),
				() -> assertTrue(after > before,
						"while a rule-steering cooldown is pending every clock tick is planning evidence"));
	}

	/*
	 * Publication path, not planning or precompilation: lifecycleBlocked() runs the lifecycle decision with the
	 * contract's envelope and so restores the planned envelope another planning overwrote in between. A sibling's
	 * regression limit (the best eligible alternative's planned upper) changes; the publication taught nothing else.
	 */
	@Test
	void publicationTimeLifecycleDecisionThatRestoresAPlannedEnvelopeAdvancesThePlanningRevision(
			@TempDir Path directory) throws Exception {
		LmdbOperatorFeedbackStats stats = stats(directory, new AtomicLong());
		RuntimeFeedbackTarget target = stats.resolveRuntimeFeedbackTarget(tokenLifecycleContract());
		target.open();
		// No actual physical implementation is recorded: the lifecycle observation itself is not admissible.
		target.close(6L, 60.0d, 6L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, TerminationClassification.EXHAUSTED);
		stats.planLifecycleDecision(logical("lifecycle"), PHYSICAL, APPLICABILITY,
				new PlanLifecycleStore.ObjectiveEnvelope(5.0d, 6.0d, 7.0d));
		PlanLifecycleStore.Decision before = siblingDecision(stats);
		long revision = stats.planningRevision();

		stats.publishRuntimeFeedbackTargets(new RuntimeFeedbackTarget[] { target }, 1, true);
		PlanLifecycleStore.Decision after = siblingDecision(stats);

		assertAll(
				() -> assertEquals(7.0d, before.regressionLimit(),
						"COVERAGE_PREREQUISITE: the sibling's limit is the other planning's planned upper"),
				() -> assertEquals(70.0d, after.regressionLimit(),
						"COVERAGE_PREREQUISITE: the publication restored the contract's planned envelope"),
				() -> assertTrue(stats.planningRevision() > revision,
						"a publication-time lifecycle decision that changes a decision input is planning evidence"));
	}

